/// <summary>
/// CB223_PalletRounding
/// Batch service class for Post pricing order optimisation
/// </summary>
class METSalesOrderCreditMgmtCheckTaskService extends METSysOperationTaskService
{
    guid    topPickingProcessId;
    SalesId salesId;

}

Method.Source:
/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSalesOrderCreditMgmtCheckContract</c>.
/// </param>
public void process(METSalesOrderCreditMgmtCheckContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>
/// Process the batch tasks.
/// </summary>
/// <param name = "_readPast">Read past table setting.</param>
public void processTask(boolean _readPast)
{
    boolean success;

    while (this.getSalesIdFromTopPickingQueue(topPickingProcessId, _readPast))
    {
        try
        {
            if (this.salesId)
            {
                SalesTable salesTable = SalesTable::find(this.salesId);

                if (salesTable &&  salesTable.METCreditCheckSalesOrder == NoYes::No)
                {                        
                    ttsbegin;

                    this.execute(salesTable);

                }
            }
        }
        catch (Exception::Error)
        {
            error(strFmt("@MET:CreditCheckFail", this.SalesId));
        }
    }
}

/// <summary>
/// Initializes the object.
/// </summary>
protected void initialise()
{
    super();

    // get the topPickingProcessId from the contract
    METSalesOrderCreditMgmtCheckContract contract = dataContract as METSalesOrderCreditMgmtCheckContract;
    topPickingProcessId = contract.parmTopPickingProcessId();
}

/// <summary>
/// Executes the main processes pallet rounding, quota min/max and leter credit check.
/// </summary>
/// <param name = "_salesTable">Sales order to process.</param>
/// <returns>True if all lines processed for pallet rounding and quotas; otherwise, false.</returns>
private boolean execute(SalesTable _salesTable)
{
    boolean success = true;

    METSalesTable::runCustomCreditCheckForSalesOrder(_salesTable);

    return success;
}

/// <summary>
/// Get sales order id to substitute from the top picking queue <c>METSalesOrderCreditMgmtCheckQueue</c>
/// </summary>
/// <param name = "_processId">Guid created and added in the contract <c>METSalesOrderCreditMgmtCheckContract</c></param>
/// <param name = "_readPast">boolean to read past records or not</param>
/// <returns>Get sales order id to substitute</returns>
private SalesId getSalesIdFromTopPickingQueue(guid _processId, boolean _readPast)
{
    METSalesOrderCreditMgmtCheckQueue postQueue;

    #OCCRetryCount
    int backOffWait;
    Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
    Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
    Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

    postQueue.readPast(_readPast);

    try
    {
        ttsbegin;

        select firstonly pessimisticlock SalesId
            from postQueue
                where postQueue.ProcessId == _processId;

        if (postQueue.RecId)
        {
            this.salesId = postQueue.SalesId;

            postQueue.delete();
        }
        else
        {
            // no sales order id found from top picking queue
            this.salesId = '';
        }

        ttscommit;
    }
    catch (deadLockException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw deadLockException;
            }
        }
        else
        {
            throw deadLockException;
        }
    }
    catch (updateConflictException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        else
        {
            throw updateConflictException;
        }
    }
    catch (transientSqlConnectionError)
    {
        if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
        {
            retry;
        }
        else
        {
            throw transientSqlConnectionError;
        }
    }

    return this.salesId;  
}
